-- ============================================= -- Author: <Author,,Name> -- Create date: <Create Date,,> -- Description: <Description,,> -- ============================================= CREATE PROCEDURE [dbo].[AddGdata] -- Add the parameters for the stored procedure here @_machineNumber int, @_enrollNumber int, @_enrollMachineNumber int, @_verifyMode int, @_inOutMode int, @_year int, @_month int, @_day int, @_hour int, @_minute int, @takeJoureny int, @_statu bit
AS BEGIN -- SET NOCOUNT ON added to prevent extra result sets from -- interfering with SELECT statements. SET NOCOUNT ON;
insert into Attendance(_machineNumber,_enrollNumber, _enrollMachineNumber,_verifyMode,_inOutMode,_year,_month,_day,_hour,_minute,takeJoureny,_statu)values(@_machineNumber,@_enrollNumber,@_enrollMachineNumber,@_verifyMode,@_inOutMode,@_year,@_month,@_day,@_hour,@_minute,@takeJoureny,@_statu)
END /****** Object: StoredProcedure [dbo].[CalcItemStock] Script Date: 5/25/2021 1:42:26 PM ******/ SET ANSI_NULLS ON GO SET QUOTED_IDENTIFIER ON GO CREATE PROCEDURE [dbo].[CalcItemStock] @branch [int], @Inventory [int], @item [int], @stock Float out WITH EXECUTE AS CALLER AS BEGIN set @stock = (select sum(stockIn - stockOut) as ItemStock from ( select ItemId,sum(val) as stockIn, 0 as stockOut from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id where inv_sub.proc_type=1 and Inv_Sub.ItemId=@item and inv_sub.store=@Inventory and (@branch is null or inv.branch=@branch) and inv.IS_Deleted=0 group by ItemId,inv_sub.store union select ItemId,0 as stockIn, sum(val) as stockOut from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id where inv_sub.proc_type=2 and Inv_Sub.ItemId=@item and inv_sub.store =@Inventory and (@branch is null or inv.branch=@branch) and inv.IS_Deleted=0 group by ItemId,inv_sub.store) as tb ) if (@stock is null) set @stock=0 END GO
/****** Object: UserDefinedFunction [dbo].[TotalItemStockInventory] Script Date: 6/15/2021 4:30:57 PM ******/ SET ANSI_NULLS ON GO
SET QUOTED_IDENTIFIER ON GO
CREATE function [dbo].[TotalItemStockInventory](@branch int,@date datetime ,@Inventory int=1) returns table as return( select itemId, sum(stockIn - stockOut)as Stock,Category,Inventory from (select ItemId,sum(val) as stockIn, 0 as stockOut,inv_sub.store as Inventory ,ItemsCategory.id as Category from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=1 and inv_sub.store =@Inventory and (@branch is null or inv.branch=@branch) and Inv.date<=@date and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id union select ItemId,0 as stockIn, sum(val) as stockOut ,inv_sub.store as Inventory ,ItemsCategory.id as Category from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=2 and inv_sub.store =@Inventory and (@branch is null or inv.branch=@branch) and Inv.date<=@date and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id) as tb group by ItemId,Inventory,Category)
GO /****** Object: UserDefinedFunction [dbo].[TotalItemStock] Script Date: 6/15/2021 4:30:00 PM ******/ SET ANSI_NULLS ON GO
SET QUOTED_IDENTIFIER ON GO
CREATE function [dbo].[TotalItemStock](@branch int,@date datetime ) returns table as return( select itemId, sum(stockIn - stockOut)as Stock,Category from (select ItemId,sum(val) as stockIn, 0 as stockOut ,ItemsCategory.id as Category from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=1 and inv_sub.store is not null and (@branch is null or inv.branch=@branch) and Inv.date<=@date and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id union select ItemId,0 as stockIn, sum(val) as stockOut,ItemsCategory.id as Category from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=2 and inv_sub.store is not null and (@branch is null or inv.branch=@branch) and Inv.date<=@date and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id) as tb group by ItemId,Category) GO /****** Object: UserDefinedFunction [dbo].[Inventorybalance] Script Date: 6/15/2021 4:29:54 PM ******/ SET ANSI_NULLS ON GO
SET QUOTED_IDENTIFIER ON GO
CREATE function [dbo].[Inventorybalance]() returns table as return( select itemId, sum(stockIn - stockOut)as Stock,Inventory from (select ItemId,sum(val) as stockIn, 0 as stockOut,inv_sub.store as Inventory from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=1 and inv_sub.store is not null and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id union select ItemId,0 as stockIn, sum(val) as stockOut ,inv_sub.store as Inventory from inv left join inv_sub on inv.InvGlobalId=inv_sub.InvGlobalId left join Items on inv_sub.ItemId= Items.id left join ItemsCategory on items.group_id= ItemsCategory.id where inv_sub.proc_type=2 and inv_sub.store is not null and inv.IS_Deleted=0 group by ItemId,inv_sub.store,ItemsCategory.id) as tb group by ItemId,Inventory) GO /****** Object: UserDefinedFunction [dbo].[SalesByDay] Script Date: 10/22/2024 12:57:59 PM ******/ SET ANSI_NULLS ON GO
SET QUOTED_IDENTIFIER ON GO
CREATE function [dbo].[SalesByDay](@branch int,@InvType int,@StartDate dateTime,@EndDate dateTime ) returns table as return(select InvDate ,sum(SaleTotal - ReturnSaleTotal) as Total,sum(SaleTax - ReturnSaleTax) as TotalTax, sum(InvTotal-ReturnTotal) as SaleNet,ROW_NUMBER() OVER (ORDER BY InvDate DESC) AS RowNum from (select CAST(date AS DATE) as InvDate, sum(tot_net) as InvTotal, sum(inv.InvTotal) as SaleTotal, sum(tax) as SaleTax , 0 as InvReturnCount,0 as ReturnTotal,0 as ReturnSaleTotal,0 as ReturnSaleTax from inv where (@branch is null or branch =@branch ) and (inv_type=@InvType) and proc_type=1 and IS_Deleted=0 and pay_type <>5 and (@StartDate is null or date>=@StartDate)and (@EndDate is null or date<=@EndDate) group by date union all select CAST(date AS DATE) as InvDate ,0 as InvCount,0 as InvTotal,0 as SaleTotal,0 as SaleTax, sum(tot_net) as ReturnTotal , sum(inv.InvTotal) as ReturnSaleTotal,sum(tax) as ReturnSaleTax from inv where ( @branch is null or branch =@branch ) and (inv_type=@InvType) and proc_type=2 and IS_Deleted=0 and pay_type <>5 and (@StartDate is null or date>=@StartDate)and (@EndDate is null or date<=@EndDate) group by date ) as tb group by tb.InvDate ) GO
/****** Object: StoredProcedure [dbo].[InventoryCostByType] Script Date: 6/16/2021 2:19:00 PM ******/ SET ANSI_NULLS ON GO
