CREATE PROCEDURE [dbo].[GetSalesByPaymentMethods] @branch [int] , @inv_type [int] , @StartDate dateTime , @EndDate dateTime
WITH EXECUTE AS CALLER AS BEGIN select '' as PayMethod, PayTypeID, sum(Sales) as TotalSales,sum(ReturnSales) as ReturnSales , sum(Sales-ReturnSales) as SaleNet from (select pay_type as PayTypeID , count(*) as InvCount, CASE WHEN pay_type = 1 THEN sum(tot_net) WHEN pay_type = 2 THEN sum(visa) WHEN pay_type = 4 THEN sum(visa + cash) WHEN pay_type = -1 THEN sum(tot_net) End as Sales ,0 as ReturnSales from inv where (@branch is null or branch =@branch ) and (inv_type=2 or inv_type=3) and proc_type=1 and (@StartDate is null or date>=@StartDate)and (@EndDate is null or date<=@EndDate)group by pay_type union select pay_type as PayTypeID , 0as InvCount, 0 as Sales ,CASE WHEN pay_type = 1 THEN sum(tot_net) WHEN pay_type = 2 THEN sum(visa) WHEN pay_type = 4 THEN sum(visa + cash) WHEN pay_type = -1 THEN sum(tot_net) End as ReturnSales from inv where (@branch is null or branch =@branch ) and (inv_type=2 or inv_type=3) and proc_type=2 and (@StartDate is null or date>=@StartDate)and (@EndDate is null or date<=@EndDate)group by pay_type ) as tb group by PayTypeID END GO /****** Object: StoredProcedure [dbo].[MonthlySales] Script Date: 10/2/2022 2:35:56 PM ******/ SET ANSI_NULLS ON GO SET QUOTED_IDENTIFIER ON GO CREATE PROCEDURE [dbo].[MonthlySales] @branch [int] , @inv_type [int] , @pay_type [int] , @Seller [int] WITH EXECUTE AS CALLER AS BEGIN select InvDate,InvYear,InvMonth , sum(InvCount) as InvCount,sum(InvReturnCount) as InvReturnCount ,sum(InvTotal)as InvTotal , sum(ReturnTotal) as ReturnTotal, sum(InvTotal-ReturnTotal) as SaleNet from (select CONCAT(CAST(MONTH(date) AS VARCHAR(2)) , '-' , CAST(YEAR(date) AS VARCHAR(4))) as InvDate,0 as InvCount, sum(InvTotal) as InvTotal ,0 as InvReturnCount,0 as ReturnTotal,YEAR(date) as InvYear, month(date) as InvMonth from inv where (@branch is null or branch =@branch ) and (@inv_type is null or(inv_type=@inv_type or inv_type=@inv_type)) and proc_type=1 and IS_Deleted=0 group by year(date), month(date) union all select CONCAT(CAST(MONTH(date) AS VARCHAR(2)) , '-' , CAST(YEAR(date) AS VARCHAR(4))) as InvDate ,0 as InvCount,0 as InvTotal, count(*) as InvReturnCount, sum(InvTotal) as ReturnTotal ,YEAR(date) as InvYear, month(date) as InvMonth from inv where (@branch is null or branch =@branch ) and (@inv_type is null or(inv_type=@inv_type or inv_type=@inv_type)) and proc_type=2 and IS_Deleted=0 group by year(date), month(date)) as tb group by InvDate,InvYear,InvMonth order by InvYear,InvMonth END GO /****** Object: Table [dbo].[CloudPayment] Script Date: 12/25/2022 8:22:31 PM ******/ SET ANSI_NULLS ON GO SET QUOTED_IDENTIFIER ON GO CREATE TABLE [dbo].[CloudPayment]( [ID] [int] IDENTITY(1,1) NOT NULL, [Name] [nvarchar](100) NULL, [CloudID] [nvarchar](50) NULL, CONSTRAINT [PK_CloudPayment] PRIMARY KEY CLUSTERED ( [ID] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO SET ANSI_NULLS ON GO SET QUOTED_IDENTIFIER ON GO CREATE TABLE [dbo].[CloudPaytypeSetting]( [ID] [int] NULL, [Name] [nvarchar](50) NULL, [NameEn] [nvarchar](50) NULL, [Paytype] [int] NULL, [CloudPaytypeID] [nvarchar](50) NULL, [BankId] [int] NULL ) ON [PRIMARY] GO INSERT [dbo].[CloudPaytypeSetting] ([ID], [Name], [NameEn], [Paytype], [CloudPaytypeID],[BankId]) VALUES (1, N'أجل', N'Credit', -1, N'',0) GO INSERT [dbo].[CloudPaytypeSetting] ([ID], [Name], [NameEn], [Paytype], [CloudPaytypeID],[BankId]) VALUES (2, N'نقدي', N'Cash', 1, N'',0) GO INSERT [dbo].[CloudPaytypeSetting] ([ID], [Name], [NameEn], [Paytype], [CloudPaytypeID],[BankId]) VALUES (3, N'شبكة', N'Credit card', 2, N'',1) GO INSERT [dbo].[CloudPaytypeSetting] ([ID], [Name], [NameEn], [Paytype], [CloudPaytypeID],[BankId]) VALUES (4, N'متعدد', N'Multi', 4, N'',0) GO
