CREATE FUNCTION [dbo].[funCalculateSerialNoSummary]( @ItemSerialNo NVARCHAR(50) = NULL, @itemid INT = NULL, @Branch INT = NULL ) RETURNS TABLE AS RETURN ( SELECT itemid, ItemSerialNo, SUM(stockIn - stockOut) AS result FROM ( SELECT itemid, ItemSerialNo, SUM(ItemQuantity) AS stockIn, 0 AS stockOut FROM InvoiceItemDetail LEFT JOIN Inv ON InvoiceItemDetail.InvGlobalID = Inv.InvGlobalID WHERE InvoiceItemDetail.InvertoryImpact=1 AND Inv.IS_Deleted = 0 AND (@ItemSerialNo IS NULL OR ItemSerialNo = @ItemSerialNo) AND (@itemid IS NULL OR itemid = @itemid) GROUP BY itemid, ItemSerialNo
UNION ALL
SELECT itemid, ItemSerialNo, 0 AS stockIn, SUM(ItemQuantity) AS stockOut FROM InvoiceItemDetail LEFT JOIN Inv ON InvoiceItemDetail.InvGlobalID = Inv.InvGlobalID WHERE Inv.IS_Deleted = 0 AND InvoiceItemDetail.InvertoryImpact=2 AND (@ItemSerialNo IS NULL OR ItemSerialNo = @ItemSerialNo) AND (@itemid IS NULL OR itemid = @itemid) AND (@Branch IS NULL OR inv.branch = @Branch) GROUP BY itemid, ItemSerialNo ) AS tb GROUP BY itemid, ItemSerialNo ); GO /****** Object: UserDefinedFunction [dbo].[funGetInvoiceItemDetails] Script Date: 10/8/2023 1:34:59 PM ******/ SET ANSI_NULLS ON GO
