CREATE PROCEDURE [dbo].[proGetCategorySaleByDay] @branch INT, @inv_type INT, @StartDate DATE, @EndDate DATE, @CategoryID INT AS BEGIN SELECT ItemsCategory.name AS CategoryName, ItemsCategory.Code AS CtgyCode, ItemsCategory.CategoryID, SUM(Sales) AS Sales, SUM(ReturnSales) AS ReturnSales, SUM(Sales - ReturnSales) - SUM(InvoiceDiscount1 - InvoiceDiscount2) AS SaleNet, InvDate FROM ( SELECT ItemId , SUM((val1 * exchange_price) - discount) as Sales ,0 as ReturnSales, SUM(round((exchange_price * minus /InvSum),2)) InvoiceDiscount1, 0 InvoiceDiscount2, CAST(inv.date AS DATE) as InvDate FROM Inv_Sub LEFT JOIN inv ON Inv_Sub.InvGlobalID = Inv.InvGlobalID WHERE Inv.IS_Deleted = 0 AND (@branch IS NULL OR branch = @branch) AND inv_type = @inv_type AND inv.proc_type=1 AND (@StartDate IS NULL OR date >= @StartDate) AND (@EndDate IS NULL OR date <= @EndDate) GROUP BY ItemId, inv.date UNION ALL SELECT ItemId , 0 as Sales , SUM((val1 * exchange_price) - discount) as ReturnSales, 0 InvoiceDiscount1, SUM(round((exchange_price * minus /InvSum),2)) InvoiceDiscount2, CAST(inv.date AS DATE) as InvDate FROM Inv_Sub LEFT JOIN inv ON Inv_Sub.InvGlobalID = Inv.InvGlobalID WHERE Inv.IS_Deleted = 0 AND (@branch IS NULL OR branch = @branch) AND inv_type = @inv_type AND inv.proc_type=2 AND (@StartDate IS NULL OR date >= @StartDate) AND (@EndDate IS NULL OR date <= @EndDate) GROUP BY ItemId, inv.date ) AS tb
LEFT JOIN Items ON Items.id = tb.ItemId LEFT JOIN ItemsCategory ON Items.group_id = ItemsCategory.CategoryId where (@CategoryID IS NULL OR ItemsCategory.CategoryID = @CategoryID) GROUP BY CategoryID, ItemsCategory.name, ItemsCategory.Code, tb.InvDate ORDER BY InvDate DESC; END GO CREATE TABLE [dbo].[priceTypes]( [id] [int] IDENTITY(1,1) NOT NULL, [TypeId] [nvarchar](20) NULL, [TypeName] [nvarchar](50) NULL, CONSTRAINT [PK_priceTypes] PRIMARY KEY CLUSTERED ( [id] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO /****** Object: Table [dbo].[CloudPaytypeSetting] Script Date: 1/7/2024 8:26:00 PM ******/ SET ANSI_NULLS ON GO
