Create PROCEDURE [dbo].[GetAccountStatement] @ParentCode NVARCHAR(50), @StartDate DATETIME, @EndDate DATETIME, @Branch NVARCHAR(50), @ShowPreviousBalance BIT AS BEGIN SET NOCOUNT ON;
-- CTE to get account hierarchy WITH AccountHierarchy AS ( SELECT Code, AName, Type, ParentCode FROM Accounts_Index WHERE Code = @ParentCode
UNION ALL
SELECT a.Code, a.AName, a.Type, a.ParentCode FROM Accounts_Index a INNER JOIN AccountHierarchy ah ON a.ParentCode = ah.Code ),
-- CTE to calculate previous balance for child accounts PreviousBalance AS ( SELECT @ParentCode AS Code, SUM(es.dept) as PreviousDept, SUM(es.credit) AS PreviousCredit FROM entry e INNER JOIN entry_sub es ON e.GlobalID = es.EntryGlobalID WHERE es.acc_no IN (SELECT Code FROM AccountHierarchy WHERE Type = 2) AND e.is_Deleted = 0 -- Exclude deleted entries if needed AND e.date < @StartDate AND (@Branch IS NULL OR e.branch = @Branch) ),
-- CTE to get the main statement MainStatement AS ( SELECT ROW_NUMBER() OVER (ORDER BY e.date) AS DgvRank, es.acc_no AS DgvAccCode, ah.AName AS DgvAccName, e.doc_No AS DgvEntryNo, es.dept AS DgvDept, es.credit AS DgvCredit, e.date AS DgvDate, es.notes AS DgvNote, es.EntryGlobalID AS DgvGenralNo, b.name AS DgvBranch, 0 as DgvBalance, '' DgvBalanceStatus, et.Name AS DgvEntryType FROM entry e INNER JOIN entry_sub es ON e.GlobalID = es.EntryGlobalID INNER JOIN AccountHierarchy ah ON es.acc_no = ah.Code LEFT JOIN Branches b ON e.branch = b.BranchId LEFT JOIN EntryTypes et on e.type=et.Id WHERE es.acc_no IN (SELECT Code FROM AccountHierarchy) AND e.is_Deleted = 0 -- Exclude deleted entries if needed AND (@StartDate IS NULL OR e.date >= @StartDate) AND (@EndDate IS NULL OR e.date <= @EndDate) AND (@Branch IS NULL OR e.branch = @Branch) )
-- Combine the previous balance with the main statement based on @ShowPreviousBalance SELECT DgvRank, DgvAccCode, DgvAccName, DgvEntryNo, DgvDept, DgvCredit, DgvDate, DgvNote, DgvGenralNo, DgvBranch, DgvBalance, DgvBalanceStatus, DgvEntryType FROM ( -- Previous balance row SELECT 0 AS DgvRank, -- Use -1 to ensure it appears first pb.Code AS DgvAccCode, ai.AName AS DgvAccName, NULL AS DgvEntryNo, pb.PreviousDept AS DgvDept, pb.PreviousCredit AS DgvCredit, @StartDate AS DgvDate, 'Previous Balance' AS DgvNote, NULL AS DgvGenralNo, NULL AS DgvBranch, 0 AS DgvBalance, 'Previous Balance' DgvBalanceStatus, 'Previous Balance' AS DgvEntryType FROM PreviousBalance pb INNER JOIN Accounts_Index ai ON pb.Code = ai.Code WHERE @ShowPreviousBalance = 1
UNION ALL
-- Main statement rows SELECT ms.DgvRank, ms.DgvAccCode, ms.DgvAccName, ms.DgvEntryNo, ms.DgvDept, ms.DgvCredit, ms.DgvDate, ms.DgvNote, ms.DgvGenralNo, ms.DgvBranch, ms.DgvBalance, ms.DgvBalanceStatus, ms.DgvEntryType FROM MainStatement ms ) AS CombinedResult ORDER BY DgvRank, DgvDate; END; GO CREATE TABLE [dbo].[Year_Previews]( [id] [int] IDENTITY(1,1) NOT NULL, [Dbname] [nvarchar](150) NULL, [DbAutoName] [nvarchar](350) NULL, [IS_Deleted] [bit] NULL, CONSTRAINT [PK_Year_Previews] PRIMARY KEY CLUSTERED ( [id] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO CREATE TABLE [dbo].[Settingmqtt]( [id] [int] IDENTITY(1,1) NOT NULL, [clientid] [nvarchar](50) NULL, [nodeid] [nvarchar](50) NULL, [frequency] [nvarchar](50) NULL, [sale] [nvarchar](50) NULL, [receipt] [nvarchar](50) NULL, [income] [nvarchar](50) NULL, [finance] [nvarchar](50) NULL, [passcode] [nvarchar](50) NULL, [servername] [nvarchar](50) NULL, [usrname] [nvarchar](50) NULL, [pwd] [nvarchar](50) NULL, [DB] [nvarchar](50) NULL, [publickey] [nvarchar](50) NULL, [privatekey] [nvarchar](50) NULL, [IS_Play] [bit] NULL, [inventory] [nvarchar](50) NULL, [is_active] [bit] null, [BranchId] [int] null, [IpServer] [nvarchar](50) null, [syncItems] [bit] null, [syncDefinitions][bit] null, [syncOper][bit] null, CONSTRAINT [PK_Settingmqtt] PRIMARY KEY CLUSTERED ( [id] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] CREATE TABLE Documents ( Id INT PRIMARY KEY IDENTITY, FileName NVARCHAR(255), FileUrl nvarchar(MAX), GlobalId nvarchar(250), type int null ) CREATE TABLE [dbo].[Tables]( [Id] [int] IDENTITY(1,1) NOT NULL, [TableName] [nvarchar](120) NULL, [Cat_ID] [int] NULL, [Status] [bit] NULL, [Balance] [decimal](18, 2) NULL, [InvGlobalID] [nvarchar](150) NULL, CONSTRAINT [PK_Tables] PRIMARY KEY CLUSTERED ( [Id] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO CREATE TABLE [dbo].[Cat_Table]( [Cat_ID] [int] IDENTITY(1,1) NOT NULL, [Cat_Name] [nvarchar](50) NULL, [emp][int] null, CONSTRAINT [PK_Cat_Table] PRIMARY KEY CLUSTERED ( [Cat_ID] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO CREATE TABLE [dbo].[Table_Order]( [id] [int] IDENTITY(1,1) NOT NULL, [InvGlobalID] [nvarchar](50) NULL, [ItemId] [int] NULL, [IsNew] [bit] NULL, CONSTRAINT [PK_Table_Order] PRIMARY KEY CLUSTERED ( [id] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] GO CREATE TABLE [dbo].[InvContratct]( [InvGlobalID] [varchar](20) NOT NULL, [proc_id] [int] IDENTITY(1,1) NOT NULL, [proc_type] [int] NULL, [id] [int] NULL, [date] [datetime] NULL, [inv_type] [int] NULL, [safe] [int] NULL, [stock] [int] NULL, [cust_id] [int] NULL, [sales_emp] [int] NULL, [InvTotal] [float] NULL, [tot_purch] [float] NULL, [AdditionsTot] [float] NULL, [Insurance] [float] NULL, [tot_net] [float] NULL, [EntryID] [int] NULL, [purch_rest_id] [int] NULL, [Reff_No] [varchar](20) NULL, [Reff_date] [datetime] NULL, [branch] [int] NULL, [IS_Buy] [bit] NULL, [minus] [float] NULL, [paid] [float] NULL, [salesman] [int] NULL, [tax] [float] NULL, [ExtraVAT] [float] NULL, [pay_type] [int] NULL, [bank] [int] NULL, [cash] [float] NULL, [visa] [float] NULL, [notes] [nvarchar](150) NULL, [IS_Deleted] [bit] NULL, [Sync] [bit] NULL, [InvProfit] [float] NULL, [InvoiceStatus] [int] NULL, [AdditionalCost] [float] NULL, [PriceIncVAT] [bit] NULL, [PaymentStatus] [int] NULL, [IssueDate] [datetime] NULL, [InvCombinedId] [nvarchar](20) NULL, [ItemsDiscount] [float] NULL, [InvCost] [float] NULL, [FreeVATSales] [float] NULL, [InvSum] [float] NULL, [VATPerce